def evaluate_forward_ref(
    forward_ref: ForwardRef,
    globalns: GlobalsNamespace | None = None,
    localns: MappingNamespace | None = None,
    parent_depth: int = 0,
) -> Any:
    """Evaluate a forward reference.

    Args:
        forward_ref: The forward reference to evaluate.
        globalns: The global namespace to use.
        localns: The local namespace to use.
        parent_depth: The depth of the parent namespace to use.

    Returns:
        The evaluated type.
